function execute(input) {
  // Phase 2: write the PO, the coding and the posting date to Zip, then send the bill for approval.
  // The write switch is OFF. It goes on only after the shadow run meets the bar (D3) and
  // Betterment changes Zip so that a bill posts to NetSuite only after approval (O10).
  // Endpoints: PATCH /invoices/{id}, PATCH /invoices/{id}/line_items/{lineItemId},
  //   PATCH /invoices/{id}/send_for_approval. The set-PO endpoint is to confirm (O3).
  const enabled = input.write_enabled === true || input.write_enabled === 'true';
  if (!enabled) {
    return { written: false, zip_note: 'Phase 1: the write switch is off. The proposal goes to Slack, and AP applies it in Zip.' };
  }
  return { written: false, zip_note: 'The write switch is on, but the Zip write is not built yet (Phase 2).' };
}

function execute(input) {
  // Confidence gate. The agent proceeds only when no hard rule hit and the confidence is at or
  // above the threshold. Betterment can change the threshold (decision D6, start value 0.90).
  const parse = v => {
    if (v === null || v === undefined || v === '') return null;
    if (typeof v !== 'string') return v;
    try { return JSON.parse(v); } catch (e) { return null; }
  };
  const threshold = Number(input.confidence_threshold || 0.9);
  const d = parse(input.decision) || {};
  const bill = parse(input.bill) || {};
  const inv = parse(input.invoice) || {};
  const conf = Number(d.confidence || 0);
  const hardHit = input.hard_rule_hit === true || input.hard_rule_hit === 'true';
  const proceed = !hardHit && conf >= threshold;
  const scoreOf = po => {
    const s = (Array.isArray(d.scores) ? d.scores : []).find(x => x && x.po === po);
    return s && s.score != null ? ' (score ' + Number(s.score).toFixed(2) + ')' : '';
  };
  const lines = Array.isArray(bill.lines) ? bill.lines : [];
  const msg = [
    proceed ? '*Proposal: PO match ready for AP*' : '*Needs a person: the agent does not guess*',
    'Vendor: ' + (input.vendor_name || 'unknown') + ' | Invoice: ' + (inv.invoice_number || inv.id || 'n/a') +
      (inv.amount != null ? ' | Amount: ' + inv.amount + (inv.currency ? ' ' + inv.currency : '') : ''),
    input.zip_url ? 'Zip: <' + input.zip_url + '|Open the invoice in Zip>' : 'Zip: link not available',
    'Route: PO-backed, ' + (d.method === 'several_open_pos' ? 'several open POs (scored)' : 'one open PO (checked)'),
    'Selected PO: ' + (d.selected_po || 'none') + scoreOf(d.selected_po) +
      (d.second_best_po ? ' | Second-best PO: ' + d.second_best_po + scoreOf(d.second_best_po) : ''),
    'Confidence: ' + conf.toFixed(2) + ' (threshold ' + threshold.toFixed(2) + ')',
    'Posting date: ' + (input.posting_date || 'none') + (input.posting_rule ? ' (' + input.posting_rule + ')' : '')
  ];
  if (lines.length) {
    msg.push('Bill lines: ' + lines.map(l => l.amount + ' to GL ' + (l.gl_account || '?') + ', ' + (l.department || '?') +
      (l.line_of_business ? ', ' + l.line_of_business : '')).join(' | '));
  }
  if (hardHit) msg.push('Hard rules: ' + input.hard_rule_reasons);
  msg.push('Reasons: ' + (d.reasoning || 'n/a'));
  msg.push(proceed
    ? 'Action: check the proposal, then link the PO and create the bill in Zip.'
    : 'Action: select the correct PO in Zip, or reject the invoice and ask for the correct PO.');
  return {
    route: proceed ? 'proceed' : 'human',
    route_reason: hardHit ? 'hard rule: ' + input.hard_rule_reasons
      : (proceed ? 'confidence at or above the threshold' : 'confidence below the threshold'),
    slack_message: msg.join('\n')
  };
}

function execute(input) {
  // Hard rules H1 to H8. A hard rule always sends the invoice to a person, at any confidence.
  // H9 (invoice on hold or with an alert in Zip) is in the intake agent: it creates no task.
  const parse = v => {
    if (v === null || v === undefined || v === '') return null;
    if (typeof v !== 'string') return v;
    try { return JSON.parse(v); } catch (e) { return null; }
  };
  const yes = v => v === true || v === 'true';
  const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '').replace(/^po/, '');
  const subName = s => String((s && typeof s === 'object') ? (s.name || s.id || '') : (s || ''));
  const d = parse(input.decision) || {};
  const bill = parse(input.bill) || {};
  const inv = parse(input.invoice) || {};
  const posList = parse(input.open_pos);
  const pos = Array.isArray(posList) ? posList : [];
  const tolerance = Number(input.tolerance || 0);
  const po = pos.find(p => (d.selected_po_id && String(p.id) === String(d.selected_po_id)) ||
                           norm(p.po_number) === norm(d.selected_po)) || null;
  const hits = [];
  const add = (id, text) => hits.push({ id: id, text: id + ': ' + text });

  if (!input.invoice_id || !input.vendor_id) add('H7', 'the payload is not complete, or the vendor is not in Zip. Check the fraud signals');
  if (yes(input.requires_printed_po) && !input.printed_po_number) add('H1', (input.vendor_name || 'The vendor') + ' needs a printed PO number, and the invoice has none');
  if (!po) {
    add('H7', 'no PO was selected, or the selected PO is not an open PO of the vendor');
  } else {
    const invSub = String(input.subsidiary || inv.subsidiary || '');
    const poSub = subName(po.subsidiary);
    if (invSub && poSub && norm(invSub) !== norm(poSub)) add('H2', 'the PO is for ' + poSub + ', and the invoice is for ' + invSub);
    const remaining = po.remaining != null ? Number(po.remaining)
      : Number(po.total_amount || 0) - Number(po.amount_billed || 0) + Number(po.amount_credited || 0);
    const amount = Number(bill.subtotal != null ? bill.subtotal : (inv.amount || 0));
    if ((po.remaining != null || po.total_amount != null) && remaining + tolerance < amount) {
      add('H3', 'the remaining balance on the PO (' + remaining + ') is less than the invoice amount (' + amount + ')');
    }
    if (inv.service_start && po.start_date && po.end_date &&
        (inv.service_start < po.start_date || (inv.service_end || inv.service_start) > po.end_date)) {
      add('H5', 'the service period (' + inv.service_start + ' to ' + (inv.service_end || inv.service_start) +
        ') is outside the PO dates (' + po.start_date + ' to ' + po.end_date + '). Reject the invoice and ask for the correct PO');
    }
    if (yes(input.printed_po_reliable) && input.printed_po_number && norm(input.printed_po_number) !== norm(po.po_number)) {
      add('H8', 'the printed PO number (' + input.printed_po_number + ') is reliable for this vendor and points to a different PO');
    }
  }
  if (yes(d.needs_more_than_one_po)) add('H4', 'the invoice lines need more than one PO. Zip links one invoice to one PO only');
  if (yes(input.prepaid_candidate)) add('H6', 'the invoice is a prepaid candidate (rule P4). A person does a prepaid review');
  if (input.unmapped_lines) add('Lines', 'a line does not map to a PO line: ' + input.unmapped_lines);

  return {
    hard_rule_hit: hits.length > 0,
    hard_rules_hit: hits.map(h => h.id).join(', '),
    hard_rule_reasons: hits.map(h => h.text).join('; ')
  };
}

function execute(input) {
  // Reads the open POs of the vendor and the request history from Zip.
  // TODO (needs the Zip key and docs, O2 and O3):
  //   GET /purchase_orders?vendor_id={vendor_id} with the open status, then GET /purchase_orders/{id}.
  //   Keep for each PO: id, po_number, title, start_date, end_date, total_amount, amount_billed,
  //   amount_credited, remaining (total - billed + credited), subsidiary, department, requester,
  //   line_items (id, description, amount, gl_account, department, location, line_of_business).
  //   requester_history: GET /requests for this vendor and the original request of each PO.
  //   zip_suggested_po: the Zip auto-match, if the invoice record shows it (O3). Low trust (S8).
  // TEST ONLY: draft tasks send invoice.test_open_pos, invoice.test_requester_history and
  //   invoice.test_zip_suggested_po. Remove this before go-live.
  const parse = v => { if (typeof v !== 'string') return v; try { return JSON.parse(v); } catch (e) { return null; } };
  const inv = parse(input.invoice) || {};
  const openPos = Array.isArray(inv.test_open_pos) ? inv.test_open_pos : [];
  const history = Array.isArray(inv.test_requester_history) ? inv.test_requester_history : [];
  return {
    open_pos: openPos,
    po_count: openPos.length,
    requester_history: history,
    zip_suggested_po: String(inv.test_zip_suggested_po || '')
  };
}

function execute(input) {
  // The classifier found an item that is not an invoice (high confidence).
  // Phase 1: post a note only. Phase 2: archive the item in Zip.
  // TODO (O3): Zip documents no archive endpoint. Ask the Zip contact before the write.
  const preview = String(input.document_text || '').replace(/\s+/g, ' ').slice(0, 90);
  const link = input.zip_url ? ' | <' + input.zip_url + '|Open in Zip>' : '';
  return {
    archived: false,
    archive_note: [
      '*Not an invoice: archive recommended*',
      'Item: ' + (input.vendor_name || 'unknown sender') + ' (' + (input.invoice_id || 'no id') + ')' + link,
      'Reason: ' + (input.reason || 'n/a'),
      'Preview: "' + preview + '..."',
      'Action: archive the item in the Zip Inbox. An archive is a soft delete. To undo it, restore the item from the archived items in Zip.',
      'The agent did not change Zip. Zip writes start in Phase 2.'
    ].join('\n')
  };
}

function execute(input) {
  // Prepares the bill for the selected PO: posting date (rules P1 to P4), lines and coding.
  // Code calculates the posting date, not the LLM. The coding always comes from the PO line.
  const parse = v => {
    if (v === null || v === undefined || v === '') return null;
    if (typeof v !== 'string') return v;
    try { return JSON.parse(v); } catch (e) { return null; }
  };
  const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '').replace(/^po/, '');
  const round2 = n => Math.round(Number(n || 0) * 100) / 100;
  const iso = d => d.toISOString().slice(0, 10);
  const day = s => new Date(String(s).slice(0, 10) + 'T00:00:00Z');

  // Only one of the two PO selection steps ran. Take the result that is there.
  const decision = [input.decision_multi, input.decision_single].map(parse)
    .find(d => d && typeof d === 'object' && d.path === 'po_backed') || null;
  const inv = parse(input.invoice) || {};
  const posList = parse(input.open_pos);
  const pos = Array.isArray(posList) ? posList : [];
  const holidays = (parse(input.holidays) || []).map(String);
  const prepaidMin = Number(input.prepaid_threshold || 10000);

  if (!decision) {
    return {
      decision: { path: 'unknown', confidence: 0, reasoning: 'No PO selection result' },
      bill: {}, posting_date: '', posting_rule: 'No bill: no PO selection result',
      prepaid_candidate: false, unmapped_lines: '', bill_summary: 'No bill: no PO selection result'
    };
  }
  const po = pos.find(p => (decision.selected_po_id && String(p.id) === String(decision.selected_po_id)) ||
                           norm(p.po_number) === norm(decision.selected_po)) || null;

  // Posting date. AP closes on business day 4. Business days exclude weekends and the holidays.
  // TEST ONLY: invoice.test_processing_date sets the processing date in draft tasks.
  const today = inv.test_processing_date ? day(inv.test_processing_date) : day(new Date().toISOString());
  const isBiz = d => { const w = d.getUTCDay(); return w !== 0 && w !== 6 && !holidays.includes(iso(d)); };
  let bizDay = 0;
  for (const x = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), 1)); x <= today; x.setUTCDate(x.getUTCDate() + 1)) {
    if (isBiz(x)) bizDay++;
  }
  let postingDate, rule;
  if (bizDay <= 4) {
    postingDate = iso(new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), 0)));
    rule = 'P1: processed on business day ' + bizDay + ', so the last day of the previous month';
  } else {
    postingDate = iso(today);
    rule = 'P2: processed on business day ' + bizDay + ', so the processing date (default, to confirm)';
  }
  const svcStart = inv.service_start ? day(inv.service_start) : null;
  const svcEnd = inv.service_end ? day(inv.service_end) : null;
  if (svcStart && iso(svcStart).slice(0, 7) > postingDate.slice(0, 7)) {
    postingDate = iso(svcStart).slice(0, 7) + '-01';
    rule = 'P3: the service starts in a later month, so the first day of the service month (GL team to confirm)';
  }
  const total = inv.amount != null ? Number(inv.amount) : 0;
  const longService = svcStart && svcEnd && (svcEnd - svcStart) / 86400000 > 31;
  let prepaid = false;
  if (total >= prepaidMin && longService) {
    prepaid = true;
    postingDate = '';
    rule = 'P4: total of ' + total + ' and a service period longer than one month, so no date. A person does a prepaid review.';
  }

  // Lines and coding from the PO.
  const invLines = (Array.isArray(inv.line_items) ? inv.line_items : [])
    .filter(l => !/\btax\b/i.test(String(l.description || '')));
  const subtotal = inv.subtotal != null ? Number(inv.subtotal)
    : inv.amount != null ? Number(inv.amount) - Number(inv.tax || 0)
    : invLines.reduce((a, l) => a + Number(l.amount || 0), 0);
  const poLines = po && Array.isArray(po.line_items) ? po.line_items : [];
  const coding = l => ({
    gl_account: String(l.gl_account || ''), department: String(l.department || ''),
    location: String(l.location || ''), line_of_business: String(l.line_of_business || '')
  });
  const words = s => String(s || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 1);
  const bestLine = desc => {
    const w = words(desc);
    if (!w.length) return null;
    const scored = poLines.map(p => ({ p, s: w.filter(x => words(p.description).includes(x)).length / w.length }))
      .sort((a, b) => b.s - a.s);
    if (!scored.length || scored[0].s < 0.5) return null;
    if (scored[1] && scored[1].s === scored[0].s) return null;
    return scored[0].p;
  };

  let lines = [];
  const unmapped = [];
  if (!po) {
    unmapped.push('the selected PO is not in the open POs of the vendor');
  } else if (poLines.length <= 1) {
    const src = poLines[0] || po;
    lines = [Object.assign({
      description: (po.title || po.po_number || 'Invoice') + (inv.service_start ? ' (service ' + inv.service_start + ')' : ''),
      amount: round2(subtotal),
      po_line: String((poLines[0] && (poLines[0].id || poLines[0].description)) || '')
    }, coding(src))];
  } else {
    const map = Array.isArray(decision.line_map) ? decision.line_map : [];
    const groups = {};
    invLines.forEach((l, i) => {
      const m = map.find(x => Number(x.invoice_line) === i);
      let target = m ? poLines.find(p => String(p.id) === String(m.po_line) || p.description === m.po_line) : null;
      if (!target) target = bestLine(l.description);
      if (!target) { unmapped.push(String(l.description || 'line ' + (i + 1))); return; }
      const key = String(target.id || target.description);
      if (!groups[key]) groups[key] = Object.assign({ description: String(target.description || ''), amount: 0, po_line: key }, coding(target));
      groups[key].amount = round2(groups[key].amount + Number(l.amount || 0));
    });
    lines = Object.values(groups);
  }

  const bill = {
    po: decision.selected_po, po_id: po ? String(po.id || '') : '',
    posting_date: postingDate, posting_rule: rule, business_day: bizDay,
    subtotal: round2(subtotal), lines: lines
  };
  const summary = 'Bill for ' + decision.selected_po + ': posting date ' + (postingDate || 'none') + ' (' + rule.split(':')[0] + '), ' +
    lines.length + ' line(s): ' + lines.map(l => l.amount + ' to GL ' + (l.gl_account || '?') + ' / ' + (l.department || '?') +
    (l.line_of_business ? ' / ' + l.line_of_business : '')).join('; ');
  return {
    decision: decision, bill: bill, posting_date: postingDate, posting_rule: rule,
    prepaid_candidate: prepaid, unmapped_lines: unmapped.join('; '), bill_summary: summary
  };
}

function execute(input) {
  // The vendor has exactly one open PO. Code checks it. No LLM.
  // The hard rules (later step) send the invoice to a person when a check fails.
  const parse = v => { if (typeof v !== 'string') return v; try { return JSON.parse(v); } catch (e) { return null; } };
  const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '').replace(/^po/, '');
  const subName = s => String((s && typeof s === 'object') ? (s.name || s.id || '') : (s || ''));
  const inv = parse(input.invoice) || {};
  const pos = parse(input.open_pos);
  const po = (Array.isArray(pos) && pos[0]) || {};
  const lines = Array.isArray(inv.line_items) ? inv.line_items : [];
  const subtotal = inv.subtotal != null ? Number(inv.subtotal)
    : inv.amount != null ? Number(inv.amount) - Number(inv.tax || 0)
    : lines.reduce((a, l) => a + Number(l.amount || 0), 0);
  const remaining = po.remaining != null ? Number(po.remaining)
    : Number(po.total_amount || 0) - Number(po.amount_billed || 0) + Number(po.amount_credited || 0);
  const reliable = input.printed_po_reliable === true || input.printed_po_reliable === 'true';
  const failed = [];
  let confidence = 0.97;
  const invSub = String(input.subsidiary || inv.subsidiary || '');
  const poSub = subName(po.subsidiary);
  if (invSub && poSub && norm(invSub) !== norm(poSub)) { failed.push('S5: the PO subsidiary is not the invoice subsidiary'); confidence = Math.min(confidence, 0.2); }
  if (inv.service_start && po.start_date && po.end_date &&
      (inv.service_start < po.start_date || (inv.service_end || inv.service_start) > po.end_date)) {
    failed.push('S3: the service period is outside the PO dates'); confidence = Math.min(confidence, 0.3);
  }
  if ((po.remaining != null || po.total_amount != null) && remaining < subtotal) {
    failed.push('S6: the remaining balance (' + remaining + ') is less than the invoice amount (' + subtotal + ')'); confidence = Math.min(confidence, 0.4);
  }
  if (reliable && input.printed_po_number && norm(input.printed_po_number) !== norm(po.po_number)) {
    failed.push('S1: the printed PO number points to a different PO'); confidence = Math.min(confidence, 0.3);
  }
  const selected = String(po.po_number || po.id || '');
  return {
    decision: {
      path: 'po_backed',
      method: 'one_open_po',
      selected_po: selected,
      selected_po_id: String(po.id || ''),
      second_best_po: '',
      scores: [{ po: selected, score: confidence, reasons: failed.length ? failed.join('; ') : 'All checks pass' }],
      confidence: confidence,
      needs_more_than_one_po: false,
      line_map: [],
      reasoning: failed.length
        ? 'The vendor has one open PO, but a check failed: ' + failed.join('; ') + '.'
        : 'The vendor has one open PO. The subsidiary, the dates, the balance and the printed PO number agree.'
    }
  };
}
